def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    starts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if len(starts) != 1:
        return out

    r, c = starts[0]
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2

    for segment in range(200):
        dr, dc = directions[segment % 4]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] == 2:
                    return out
                out[r][c] = 3
        if segment % 2 == 1:
            length += 2

    return out
